import sys
from collections import defaultdict

def count_substrings(s, patterns):
    counts = {pattern: 0 for pattern in patterns}
    for i in range(len(s)):
        for j in range(i + 1, len(s) + 1):
            substring = s[i:j]
            if substring in patterns:
                counts[substring] += 1
    return counts

def max_pleasure(A, B, N, favorites):
    max_pleasure = 0
    for i in range(len(A) + 1):
        for j in range(len(B) + 1):
            C = A[:i] + B[j:]
            counts = count_substrings(C, favorites)
            current_pleasure = sum(counts[pattern] * beauty for pattern, beauty in favorites.items())
            max_pleasure = max(max_pleasure, current_pleasure)
    return max_pleasure

def main():
    import sys
    input = sys.stdin.read().splitlines()
    index = 0
    T = int(input[index])
    results = []
    for _ in range(T):
        A = input[index + 1]
        B = input[index + 2]
        N = int(input[index + 3])
        favorites = {}
        for k in range(N):
            S_i, b_i = input[index + 4 + k].split()
            b_i = int(b_i)
            favorites[S_i] = b_i
        result = max_pleasure(A, B, N, favorites)
        results.append(result)
        index += 4 + N
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
